            double r1_1_0_4 = xpq * r2_0_0_4;
            vkl[1] += r0_1_0_4 * dm_ij_cache[288];
            vj_ij[18] += r0_1_0_4 * dkl[1];
            vkl[2] += r0_1_0_4 * dm_ij_cache[272];
            vj_ij[17] += r0_1_0_4 * dkl[2];
            vkl[6] += r0_1_0_4 * dm_ij_cache[64];
            vj_ij[4] += r0_1_0_4 * dkl[6];
            vkl[7] += r0_1_0_4 * dm_ij_cache[48];
            vj_ij[3] += r0_1_0_4 * dkl[7];
            double r0_2_0_4 = xpq * r1_1_0_4 + r1_0_0_4;
            vkl[2] += r0_2_0_4 * dm_ij_cache[432];
            vj_ij[27] += r0_2_0_4 * dkl[2];
            vkl[7] += r0_2_0_4 * dm_ij_cache[288];
            vj_ij[18] += r0_2_0_4 * dkl[7];
            vkl[9] += r0_2_0_4 * dm_ij_cache[64];
            vj_ij[4] += r0_2_0_4 * dkl[9];
            double r0_0_1_4 = ypq * r1_0_0_4;
            double r1_0_1_4 = ypq * r2_0_0_4;
            vkl[1] += r0_0_1_4 * dm_ij_cache[128];
            vj_ij[8] += r0_0_1_4 * dkl[1];
            vkl[2] += r0_0_1_4 * dm_ij_cache[112];
            vj_ij[7] += r0_0_1_4 * dkl[2];
            vkl[3] += r0_0_1_4 * dm_ij_cache[64];
            vj_ij[4] += r0_0_1_4 * dkl[3];
            vkl[4] += r0_0_1_4 * dm_ij_cache[48];
            vj_ij[3] += r0_0_1_4 * dkl[4];
            double r0_1_1_4 = xpq * r1_0_1_4;
            vkl[2] += r0_1_1_4 * dm_ij_cache[336];
            vj_ij[21] += r0_1_1_4 * dkl[2];
            vkl[4] += r0_1_1_4 * dm_ij_cache[288];
            vj_ij[18] += r0_1_1_4 * dkl[4];
            vkl[7] += r0_1_1_4 * dm_ij_cache[128];
            vj_ij[8] += r0_1_1_4 * dkl[7];
            vkl[8] += r0_1_1_4 * dm_ij_cache[64];
            vj_ij[4] += r0_1_1_4 * dkl[8];
            double r0_0_2_4 = ypq * r1_0_1_4 + r1_0_0_4;
            vkl[2] += r0_0_2_4 * dm_ij_cache[176];
            vj_ij[11] += r0_0_2_4 * dkl[2];
            vkl[4] += r0_0_2_4 * dm_ij_cache[128];
            vj_ij[8] += r0_0_2_4 * dkl[4];
            vkl[5] += r0_0_2_4 * dm_ij_cache[64];
            vj_ij[4] += r0_0_2_4 * dkl[5];
            double r0_0_0_5 = zpq * r1_0_0_4 + 4 * r1_0_0_3;
            double r1_0_0_5 = zpq * r2_0_0_4 + 4 * r2_0_0_3;
            vkl[1] += r0_0_0_5 * dm_ij_cache[64];
            vj_ij[4] += r0_0_0_5 * dkl[1];
            vkl[2] += r0_0_0_5 * dm_ij_cache[48];
            vj_ij[3] += r0_0_0_5 * dkl[2];
            double r0_1_0_5 = xpq * r1_0_0_5;
            vkl[2] += r0_1_0_5 * dm_ij_cache[288];
            vj_ij[18] += r0_1_0_5 * dkl[2];
            vkl[7] += r0_1_0_5 * dm_ij_cache[64];
            vj_ij[4] += r0_1_0_5 * dkl[7];
            double r0_0_1_5 = ypq * r1_0_0_5;
            vkl[2] += r0_0_1_5 * dm_ij_cache[128];
            vj_ij[8] += r0_0_1_5 * dkl[2];
            vkl[4] += r0_0_1_5 * dm_ij_cache[64];
            vj_ij[4] += r0_0_1_5 * dkl[4];
            double r0_0_0_6 = zpq * r1_0_0_5 + 5 * r1_0_0_4;
            vkl[2] += r0_0_0_6 * dm_ij_cache[64];
            vj_ij[4] += r0_0_0_6 * dkl[2];
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[0] += __shfl_down_sync(mask, vkl[0], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+0] += vkl[0]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[1] += __shfl_down_sync(mask, vkl[1], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+352] -= vkl[1]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[2] += __shfl_down_sync(mask, vkl[2], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+704] += vkl[2]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[3] += __shfl_down_sync(mask, vkl[3], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+1056] -= vkl[3]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[4] += __shfl_down_sync(mask, vkl[4], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+1408] += vkl[4]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[5] += __shfl_down_sync(mask, vkl[5], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+1760] += vkl[5]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[6] += __shfl_down_sync(mask, vkl[6], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+2112] -= vkl[6]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[7] += __shfl_down_sync(mask, vkl[7], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+2464] += vkl[7]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[8] += __shfl_down_sync(mask, vkl[8], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+2816] += vkl[8]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[9] += __shfl_down_sync(mask, vkl[9], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3168] += vkl[9]; }
        }
        {
        double *vj_cache = Rp_cache;
        int task_ij = task_ij0 + tx;
#pragma unroll
        for (int n = 0; n < 35; ++n) {
            __syncthreads();
            vj_cache[thread_id] = vj_ij[n];
            for (int stride = 8; stride > 0; stride /= 2) {
                __syncthreads();
                if (ty < stride) {
                    vj_cache[thread_id] += vj_cache[thread_id + stride*16];
                }
            }
            __syncthreads();
            if (ty == 0 && task_ij < npairs_ij) {
                atomicAdd(vj+ij_loc0+n, vj_cache[thread_id]);
            }
        }
        }
    }
    __syncthreads();
    for (int n = tx; n < 220; n += 16) {
        int kl = n / 22;
        int batch_kl = n - kl * 22;
        int sq_kl = ty + batch_kl * 16;
        int task_kl = blockIdx.y * 352 + sq_kl;
        if (task_kl < npairs_kl) {
            int kl_loc0 = pair_kl_loc[task_kl];
            atomicAdd(vj+kl_loc0+kl, vj_kl_cache[sq_kl+kl*352]);
        }
    }
}

// lij=5, lkl=1: TILEX=48 (largest; run-time tilex), TILEY=32
__global__ __launch_bounds__(256, 1) static
void md_j_gen_5_1(KERNEL_ARGS)
{
    KERNEL_SETUP();
    // the bra tile, from the grid that md_j_gen_grid_x chose
    int tilex = ((bounds.npairs_ij + 15) / 16 + gridDim.x - 1) / gridDim.x;
    int *pair_ij_mapping = bounds.pair_ij_mapping;
    int *pair_kl_mapping = bounds.pair_kl_mapping;
    int task_ij0 = block_x * (16*tilex);
    int task_kl0 = block_y * 512;
    if (q_cond_ij[task_ij0] + q_cond_kl[task_kl0] < bounds.cutoff) {
        return;
    }
    int sq_id = tx + 16 * ty;
    int thread_id = sq_id;
    int *bas = envs.bas;
    int *pair_ij_loc = bounds.pair_ij_loc;
    int *pair_kl_loc = bounds.pair_kl_loc;
    int nbas = envs.nbas;
    double *env = envs.env;
    double *vj = jk.vj;
    unsigned int lane_id = thread_id % 32;
    unsigned int group_id = lane_id / 16;
    unsigned int mask = 0xffff << (group_id * 16);

    int npairs_ij = bounds.npairs_ij;
    int npairs_kl = bounds.npairs_kl;
    double *Rq_cache = vj_kl_cache + 2048;
    double *Rp_cache = Rq_cache + 2560;
    double *dm_ij_cache = Rp_cache + 80 + tx;
    float *qd_ij_max = bounds.qd_ij_max;
    float *qd_kl_max = bounds.qd_kl_max;
    for (int n = thread_id; n < 4688; n += 256) {
        vj_kl_cache[n] = 0.;
    }
    __syncthreads();

    for (int n = thread_id; n < 512; n += 256) {
        int task_kl = blockIdx.y * 512 + n;
        if (task_kl < npairs_kl) {
            int pair_kl = pair_kl_mapping[task_kl];
            int ksh = pair_kl / nbas;
            int lsh = pair_kl % nbas;
            double ak = env[bas[ksh*BAS_SLOTS+PTR_EXP]];
            double al = env[bas[lsh*BAS_SLOTS+PTR_EXP]];
            double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
            double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
            double akl = ak + al;
            double xkl = (ak * rk[0] + al * rl[0]) / akl;
            double ykl = (ak * rk[1] + al * rl[1]) / akl;
            double zkl = (ak * rk[2] + al * rl[2]) / akl;
            Rq_cache[n+0] = xkl;
            Rq_cache[n+512] = ykl;
            Rq_cache[n+1024] = zkl;
            Rq_cache[n+1536] = akl;
            Rq_cache[n+2048] = 1. / akl;
        } else {
            Rq_cache[n+0] = 2e5;
            Rq_cache[n+512] = 2e5;
            Rq_cache[n+1024] = 2e5;
            Rq_cache[n+1536] = 1.;
            Rq_cache[n+2048] = 1.;
        }
    }

    for (int batch_ij = 0; batch_ij < tilex; ++batch_ij) {
        int task_ij0 = blockIdx.x * (16*tilex) + batch_ij * 16;
        if (task_ij0 >= npairs_ij) {
            break;
        }
        __syncthreads();
        if (thread_id < 16) {
            int task_ij = task_ij0 + thread_id;
            if (task_ij < npairs_ij) {
                int pair_ij = pair_ij_mapping[task_ij];
                int ish = pair_ij / nbas;
                int jsh = pair_ij % nbas;
                double ai = env[bas[ish*BAS_SLOTS+PTR_EXP]];
                double aj = env[bas[jsh*BAS_SLOTS+PTR_EXP]];
                double *ri = env + bas[ish*BAS_SLOTS+PTR_BAS_COORD];
                double *rj = env + bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
                double aij = ai + aj;
                double xij = (ai * ri[0] + aj * rj[0]) / aij;
                double yij = (ai * ri[1] + aj * rj[1]) / aij;
                double zij = (ai * ri[2] + aj * rj[2]) / aij;
                Rp_cache[thread_id+0] = xij;
                Rp_cache[thread_id+16] = yij;
                Rp_cache[thread_id+32] = zij;
                Rp_cache[thread_id+48] = aij;
                Rp_cache[thread_id+64] = 1. / aij;
            } else {
                Rp_cache[thread_id+0] = 2e5;
                Rp_cache[thread_id+16] = 2e5;
                Rp_cache[thread_id+32] = 2e5;
                Rp_cache[thread_id+48] = 1.; // aij
                Rp_cache[thread_id+64] = 1.;
            }
        }
        int task_ij = task_ij0 + tx;
        if (task_ij >= npairs_ij) {
            task_ij = task_ij0;
        }
        int ij_loc0 = pair_ij_loc[task_ij];
        double *dm = jk.dm + ij_loc0;
        for (int n = ty; n < 56; n += 16) {
            dm_ij_cache[n*16] = dm[n];
        }
        double vj_ij[56];
#pragma unroll
        for (int ij = 0; ij < 56; ++ij) {
            vj_ij[ij] = 0;
        }
        for (int batch_kl = 0; batch_kl < 32; ++batch_kl) {
            int task_kl0 = blockIdx.y * 512 + batch_kl * 16;
            if (task_kl0 >= npairs_kl) {
                break;
            }
            if (qd_ij_max[batch_ij+blockIdx.x*tilex] + q_cond_kl[task_kl0] < bounds.cutoff &&
                qd_kl_max[batch_kl+blockIdx.y*32] + q_cond_ij[task_ij0] < bounds.cutoff) {
                continue;
            }

            int sq_kl = ty + batch_kl * 16;
            int task_ij = task_ij0 + tx;
            int task_kl = task_kl0 + ty;
            double fac = PI_FAC;
            if (task_ij >= npairs_ij || task_kl >= npairs_kl) {
                fac = 0.;
            }
            __syncthreads();
            double xij = Rp_cache[tx+0];
            double yij = Rp_cache[tx+16];
            double zij = Rp_cache[tx+32];
            double aij = Rp_cache[tx+48];
            double inv_aij = Rp_cache[tx+64];
            double xkl = Rq_cache[sq_kl+0];
            double ykl = Rq_cache[sq_kl+512];
            double zkl = Rq_cache[sq_kl+1024];
            double akl = Rq_cache[sq_kl+1536];
            double inv_akl = Rq_cache[sq_kl+2048];
            double rs = rsqrt(aij+akl);
            fac = fac * (inv_aij * inv_akl * rs);
            double xpq = xij - xkl;
            double ypq = yij - ykl;
            double zpq = zij - zkl;
            double rr = xpq*xpq + ypq*ypq + zpq*zpq;
            double theta = aij * akl * (rs * rs);
            double omega = jk.omega;
            double gamma_inc[14];
            boys_fn(gamma_inc, theta, rr, omega, fac, 6, 0, 1);
            // the ket pair's Hermite density, with the phase (-1)^|k| of its components
            const double *dm_kl = jk.dm + pair_kl_loc[task_kl < npairs_kl ? task_kl : task_kl0];
            double dkl[4];
            dkl[0] = dm_kl[0];
            dkl[1] = -dm_kl[1];
            dkl[2] = -dm_kl[2];
            dkl[3] = -dm_kl[3];
            double vkl[4];
#pragma unroll
            for (int kl = 0; kl < 4; ++kl) {
                vkl[kl] = 0.;
            }
            vkl[0] += gamma_inc[0] * dm_ij_cache[0];
            vj_ij[0] += gamma_inc[0] * dkl[0];
            double r0_1_0_0 = xpq * gamma_inc[1];
            double r1_1_0_0 = xpq * gamma_inc[2];
            double r2_1_0_0 = xpq * gamma_inc[3];
            double r3_1_0_0 = xpq * gamma_inc[4];
            double r4_1_0_0 = xpq * gamma_inc[5];
            double r5_1_0_0 = xpq * gamma_inc[6];
            vkl[0] += r0_1_0_0 * dm_ij_cache[336];
            vj_ij[21] += r0_1_0_0 * dkl[0];
            vkl[3] += r0_1_0_0 * dm_ij_cache[0];
            vj_ij[0] += r0_1_0_0 * dkl[3];
            double r0_2_0_0 = xpq * r1_1_0_0 + gamma_inc[1];
            double r1_2_0_0 = xpq * r2_1_0_0 + gamma_inc[2];
            double r2_2_0_0 = xpq * r3_1_0_0 + gamma_inc[3];
            double r3_2_0_0 = xpq * r4_1_0_0 + gamma_inc[4];
            double r4_2_0_0 = xpq * r5_1_0_0 + gamma_inc[5];
            vkl[0] += r0_2_0_0 * dm_ij_cache[576];
            vj_ij[36] += r0_2_0_0 * dkl[0];
            vkl[3] += r0_2_0_0 * dm_ij_cache[336];
            vj_ij[21] += r0_2_0_0 * dkl[3];
            double r0_3_0_0 = xpq * r1_2_0_0 + 2 * r1_1_0_0;
            double r1_3_0_0 = xpq * r2_2_0_0 + 2 * r2_1_0_0;
            double r2_3_0_0 = xpq * r3_2_0_0 + 2 * r3_1_0_0;
            double r3_3_0_0 = xpq * r4_2_0_0 + 2 * r4_1_0_0;
            vkl[0] += r0_3_0_0 * dm_ij_cache[736];
            vj_ij[46] += r0_3_0_0 * dkl[0];
            vkl[3] += r0_3_0_0 * dm_ij_cache[576];
            vj_ij[36] += r0_3_0_0 * dkl[3];
            double r0_4_0_0 = xpq * r1_3_0_0 + 3 * r1_2_0_0;
            double r1_4_0_0 = xpq * r2_3_0_0 + 3 * r2_2_0_0;
            double r2_4_0_0 = xpq * r3_3_0_0 + 3 * r3_2_0_0;
            vkl[0] += r0_4_0_0 * dm_ij_cache[832];
            vj_ij[52] += r0_4_0_0 * dkl[0];
            vkl[3] += r0_4_0_0 * dm_ij_cache[736];
            vj_ij[46] += r0_4_0_0 * dkl[3];
            double r0_5_0_0 = xpq * r1_4_0_0 + 4 * r1_3_0_0;
            double r1_5_0_0 = xpq * r2_4_0_0 + 4 * r2_3_0_0;
            vkl[0] += r0_5_0_0 * dm_ij_cache[880];
            vj_ij[55] += r0_5_0_0 * dkl[0];
            vkl[3] += r0_5_0_0 * dm_ij_cache[832];
            vj_ij[52] += r0_5_0_0 * dkl[3];
            double r0_6_0_0 = xpq * r1_5_0_0 + 5 * r1_4_0_0;
            vkl[3] += r0_6_0_0 * dm_ij_cache[880];
            vj_ij[55] += r0_6_0_0 * dkl[3];
            double r0_0_1_0 = ypq * gamma_inc[1];
            double r1_0_1_0 = ypq * gamma_inc[2];
            double r2_0_1_0 = ypq * gamma_inc[3];
            double r3_0_1_0 = ypq * gamma_inc[4];
            double r4_0_1_0 = ypq * gamma_inc[5];
            double r5_0_1_0 = ypq * gamma_inc[6];
            vkl[0] += r0_0_1_0 * dm_ij_cache[96];
            vj_ij[6] += r0_0_1_0 * dkl[0];
            vkl[2] += r0_0_1_0 * dm_ij_cache[0];
            vj_ij[0] += r0_0_1_0 * dkl[2];
            double r0_1_1_0 = xpq * r1_0_1_0;
            double r1_1_1_0 = xpq * r2_0_1_0;
            double r2_1_1_0 = xpq * r3_0_1_0;
            double r3_1_1_0 = xpq * r4_0_1_0;
            double r4_1_1_0 = xpq * r5_0_1_0;
            vkl[0] += r0_1_1_0 * dm_ij_cache[416];
            vj_ij[26] += r0_1_1_0 * dkl[0];
            vkl[2] += r0_1_1_0 * dm_ij_cache[336];
            vj_ij[21] += r0_1_1_0 * dkl[2];
            vkl[3] += r0_1_1_0 * dm_ij_cache[96];
            vj_ij[6] += r0_1_1_0 * dkl[3];
            double r0_2_1_0 = xpq * r1_1_1_0 + r1_0_1_0;
            double r1_2_1_0 = xpq * r2_1_1_0 + r2_0_1_0;
            double r2_2_1_0 = xpq * r3_1_1_0 + r3_0_1_0;
            double r3_2_1_0 = xpq * r4_1_1_0 + r4_0_1_0;
            vkl[0] += r0_2_1_0 * dm_ij_cache[640];
            vj_ij[40] += r0_2_1_0 * dkl[0];
            vkl[2] += r0_2_1_0 * dm_ij_cache[576];
            vj_ij[36] += r0_2_1_0 * dkl[2];
            vkl[3] += r0_2_1_0 * dm_ij_cache[416];
            vj_ij[26] += r0_2_1_0 * dkl[3];
            double r0_3_1_0 = xpq * r1_2_1_0 + 2 * r1_1_1_0;
            double r1_3_1_0 = xpq * r2_2_1_0 + 2 * r2_1_1_0;
            double r2_3_1_0 = xpq * r3_2_1_0 + 2 * r3_1_1_0;
            vkl[0] += r0_3_1_0 * dm_ij_cache[784];
            vj_ij[49] += r0_3_1_0 * dkl[0];
            vkl[2] += r0_3_1_0 * dm_ij_cache[736];
            vj_ij[46] += r0_3_1_0 * dkl[2];
            vkl[3] += r0_3_1_0 * dm_ij_cache[640];
            vj_ij[40] += r0_3_1_0 * dkl[3];
            double r0_4_1_0 = xpq * r1_3_1_0 + 3 * r1_2_1_0;
            double r1_4_1_0 = xpq * r2_3_1_0 + 3 * r2_2_1_0;
            vkl[0] += r0_4_1_0 * dm_ij_cache[864];
            vj_ij[54] += r0_4_1_0 * dkl[0];
            vkl[2] += r0_4_1_0 * dm_ij_cache[832];
            vj_ij[52] += r0_4_1_0 * dkl[2];
            vkl[3] += r0_4_1_0 * dm_ij_cache[784];
            vj_ij[49] += r0_4_1_0 * dkl[3];
            double r0_5_1_0 = xpq * r1_4_1_0 + 4 * r1_3_1_0;
            vkl[2] += r0_5_1_0 * dm_ij_cache[880];
            vj_ij[55] += r0_5_1_0 * dkl[2];
            vkl[3] += r0_5_1_0 * dm_ij_cache[864];
