        }
        }
    }
    __syncthreads();
    for (int n = tx; n < 220; n += 16) {
        int kl = n / 22;
        int batch_kl = n - kl * 22;
        int sq_kl = ty + batch_kl * 16;
        int task_kl = blockIdx.y * 352 + sq_kl;
        if (task_kl < npairs_kl) {
            int kl_loc0 = pair_kl_loc[task_kl];
            atomicAdd(vj+kl_loc0+kl, vj_kl_cache[sq_kl+kl*352]);
        }
    }
}

// lij=6, lkl=1: TILEX=48 (largest; run-time tilex), TILEY=32
__global__ __launch_bounds__(256, 1) static
void md_j_gen_6_1(KERNEL_ARGS)
{
    KERNEL_SETUP();
    // the bra tile, from the grid that md_j_gen_grid_x chose
    int tilex = ((bounds.npairs_ij + 15) / 16 + gridDim.x - 1) / gridDim.x;
    int *pair_ij_mapping = bounds.pair_ij_mapping;
    int *pair_kl_mapping = bounds.pair_kl_mapping;
    int task_ij0 = block_x * (16*tilex);
    int task_kl0 = block_y * 512;
    if (q_cond_ij[task_ij0] + q_cond_kl[task_kl0] < bounds.cutoff) {
        return;
    }
    int sq_id = tx + 16 * ty;
    int thread_id = sq_id;
    int *bas = envs.bas;
    int *pair_ij_loc = bounds.pair_ij_loc;
    int *pair_kl_loc = bounds.pair_kl_loc;
    int nbas = envs.nbas;
    double *env = envs.env;
    double *vj = jk.vj;
    unsigned int lane_id = thread_id % 32;
    unsigned int group_id = lane_id / 16;
    unsigned int mask = 0xffff << (group_id * 16);

    int npairs_ij = bounds.npairs_ij;
    int npairs_kl = bounds.npairs_kl;
    double *Rq_cache = vj_kl_cache + 2048;
    double *Rp_cache = Rq_cache + 2560;
    double *dm_ij_cache = Rp_cache + 80 + tx;
    float *qd_ij_max = bounds.qd_ij_max;
    float *qd_kl_max = bounds.qd_kl_max;
    for (int n = thread_id; n < 4688; n += 256) {
        vj_kl_cache[n] = 0.;
    }
    __syncthreads();

    for (int n = thread_id; n < 512; n += 256) {
        int task_kl = blockIdx.y * 512 + n;
        if (task_kl < npairs_kl) {
            int pair_kl = pair_kl_mapping[task_kl];
            int ksh = pair_kl / nbas;
            int lsh = pair_kl % nbas;
            double ak = env[bas[ksh*BAS_SLOTS+PTR_EXP]];
            double al = env[bas[lsh*BAS_SLOTS+PTR_EXP]];
            double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
            double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
            double akl = ak + al;
            double xkl = (ak * rk[0] + al * rl[0]) / akl;
            double ykl = (ak * rk[1] + al * rl[1]) / akl;
            double zkl = (ak * rk[2] + al * rl[2]) / akl;
            Rq_cache[n+0] = xkl;
            Rq_cache[n+512] = ykl;
            Rq_cache[n+1024] = zkl;
            Rq_cache[n+1536] = akl;
            Rq_cache[n+2048] = 1. / akl;
        } else {
            Rq_cache[n+0] = 2e5;
            Rq_cache[n+512] = 2e5;
            Rq_cache[n+1024] = 2e5;
            Rq_cache[n+1536] = 1.;
            Rq_cache[n+2048] = 1.;
        }
    }

    for (int batch_ij = 0; batch_ij < tilex; ++batch_ij) {
        int task_ij0 = blockIdx.x * (16*tilex) + batch_ij * 16;
        if (task_ij0 >= npairs_ij) {
            break;
        }
        __syncthreads();
        if (thread_id < 16) {
            int task_ij = task_ij0 + thread_id;
            if (task_ij < npairs_ij) {
                int pair_ij = pair_ij_mapping[task_ij];
                int ish = pair_ij / nbas;
                int jsh = pair_ij % nbas;
                double ai = env[bas[ish*BAS_SLOTS+PTR_EXP]];
                double aj = env[bas[jsh*BAS_SLOTS+PTR_EXP]];
                double *ri = env + bas[ish*BAS_SLOTS+PTR_BAS_COORD];
                double *rj = env + bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
                double aij = ai + aj;
                double xij = (ai * ri[0] + aj * rj[0]) / aij;
                double yij = (ai * ri[1] + aj * rj[1]) / aij;
                double zij = (ai * ri[2] + aj * rj[2]) / aij;
                Rp_cache[thread_id+0] = xij;
                Rp_cache[thread_id+16] = yij;
                Rp_cache[thread_id+32] = zij;
                Rp_cache[thread_id+48] = aij;
                Rp_cache[thread_id+64] = 1. / aij;
