            vj_ij[7] += r0_0_1_6 * dkl[4];
            vkl[7] += r0_0_1_6 * dm_ij_cache[64];
            vj_ij[4] += r0_0_1_6 * dkl[7];
            vkl[8] += r0_0_1_6 * dm_ij_cache[48];
