            vj_ij[8] += r0_0_2_6 * dkl[8];
            vkl[11] += r0_0_2_6 * dm_ij_cache[64];
            vj_ij[4] += r0_0_2_6 * dkl[11];
            double r0_0_0_7 = zpq * r1_0_0_6 + 6 * r1_0_0_5;
            double r1_0_0_7 = zpq * r2_0_0_6 + 6 * r2_0_0_5;
            vkl[3] += r0_0_0_7 * dm_ij_cache[64];
            vj_ij[4] += r0_0_0_7 * dkl[3];
            vkl[4] += r0_0_0_7 * dm_ij_cache[48];
            vj_ij[3] += r0_0_0_7 * dkl[4];
            double r0_1_0_7 = xpq * r1_0_0_7;
            vkl[4] += r0_1_0_7 * dm_ij_cache[288];
            vj_ij[18] += r0_1_0_7 * dkl[4];
            vkl[18] += r0_1_0_7 * dm_ij_cache[64];
            vj_ij[4] += r0_1_0_7 * dkl[18];
            double r0_0_1_7 = ypq * r1_0_0_7;
            vkl[4] += r0_0_1_7 * dm_ij_cache[128];
            vj_ij[8] += r0_0_1_7 * dkl[4];
            vkl[8] += r0_0_1_7 * dm_ij_cache[64];
