            }
            if (tx == 0) { vj_kl_cache[sq_kl+4352] += vkl[34]; }
        }
        {
        double *vj_cache = Rp_cache;
        int task_ij = task_ij0 + tx;
#pragma unroll
        for (int n = 0; n < 35; ++n) {
            __syncthreads();
            vj_cache[thread_id] = vj_ij[n];
            for (int stride = 8; stride > 0; stride /= 2) {
                __syncthreads();
                if (ty < stride) {
                    vj_cache[thread_id] += vj_cache[thread_id + stride*16];
                }
            }
            __syncthreads();
            if (ty == 0 && task_ij < npairs_ij) {
                atomicAdd(vj+ij_loc0+n, vj_cache[thread_id]);
            }
        }
        }
    }
    __syncthreads();
    for (int n = tx; n < 280; n += 16) {
        int kl = n / 8;
        int batch_kl = n - kl * 8;
        int sq_kl = ty + batch_kl * 16;
        int task_kl = blockIdx.y * 128 + sq_kl;
        if (task_kl < npairs_kl) {
            int kl_loc0 = pair_kl_loc[task_kl];
            atomicAdd(vj+kl_loc0+kl, vj_kl_cache[sq_kl+kl*128]);
        }
    }
}

// lij=5, lkl=3: TILEX=48 (largest; run-time tilex), TILEY=13
__global__ __launch_bounds__(256, 1) static
void md_j_gen_5_3(KERNEL_ARGS)
{
    KERNEL_SETUP();
    // the bra tile, from the grid that md_j_gen_grid_x chose
    int tilex = ((bounds.npairs_ij + 15) / 16 + gridDim.x - 1) / gridDim.x;
    int *pair_ij_mapping = bounds.pair_ij_mapping;
    int *pair_kl_mapping = bounds.pair_kl_mapping;
    int task_ij0 = block_x * (16*tilex);
    int task_kl0 = block_y * 208;
    if (q_cond_ij[task_ij0] + q_cond_kl[task_kl0] < bounds.cutoff) {
        return;
    }
    int sq_id = tx + 16 * ty;
    int thread_id = sq_id;
    int *bas = envs.bas;
    int *pair_ij_loc = bounds.pair_ij_loc;
    int *pair_kl_loc = bounds.pair_kl_loc;
    int nbas = envs.nbas;
    double *env = envs.env;
    double *vj = jk.vj;
    unsigned int lane_id = thread_id % 32;
    unsigned int group_id = lane_id / 16;
    unsigned int mask = 0xffff << (group_id * 16);

    int npairs_ij = bounds.npairs_ij;
    int npairs_kl = bounds.npairs_kl;
    double *Rq_cache = vj_kl_cache + 4160;
    double *Rp_cache = Rq_cache + 1040;
    double *dm_ij_cache = Rp_cache + 80 + tx;
    float *qd_ij_max = bounds.qd_ij_max;
    float *qd_kl_max = bounds.qd_kl_max;
    for (int n = thread_id; n < 5280; n += 256) {
        vj_kl_cache[n] = 0.;
    }
    __syncthreads();

    for (int n = thread_id; n < 208; n += 256) {
        int task_kl = blockIdx.y * 208 + n;
        if (task_kl < npairs_kl) {
            int pair_kl = pair_kl_mapping[task_kl];
            int ksh = pair_kl / nbas;
            int lsh = pair_kl % nbas;
            double ak = env[bas[ksh*BAS_SLOTS+PTR_EXP]];
            double al = env[bas[lsh*BAS_SLOTS+PTR_EXP]];
            double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
            double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
            double akl = ak + al;
            double xkl = (ak * rk[0] + al * rl[0]) / akl;
            double ykl = (ak * rk[1] + al * rl[1]) / akl;
            double zkl = (ak * rk[2] + al * rl[2]) / akl;
            Rq_cache[n+0] = xkl;
            Rq_cache[n+208] = ykl;
            Rq_cache[n+416] = zkl;
            Rq_cache[n+624] = akl;
            Rq_cache[n+832] = 1. / akl;
        } else {
            Rq_cache[n+0] = 2e5;
            Rq_cache[n+208] = 2e5;
            Rq_cache[n+416] = 2e5;
            Rq_cache[n+624] = 1.;
            Rq_cache[n+832] = 1.;
        }
    }

    for (int batch_ij = 0; batch_ij < tilex; ++batch_ij) {
        int task_ij0 = blockIdx.x * (16*tilex) + batch_ij * 16;
        if (task_ij0 >= npairs_ij) {
            break;
        }
        __syncthreads();
        if (thread_id < 16) {
            int task_ij = task_ij0 + thread_id;
            if (task_ij < npairs_ij) {
                int pair_ij = pair_ij_mapping[task_ij];
                int ish = pair_ij / nbas;
                int jsh = pair_ij % nbas;
                double ai = env[bas[ish*BAS_SLOTS+PTR_EXP]];
                double aj = env[bas[jsh*BAS_SLOTS+PTR_EXP]];
                double *ri = env + bas[ish*BAS_SLOTS+PTR_BAS_COORD];
                double *rj = env + bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
                double aij = ai + aj;
                double xij = (ai * ri[0] + aj * rj[0]) / aij;
                double yij = (ai * ri[1] + aj * rj[1]) / aij;
                double zij = (ai * ri[2] + aj * rj[2]) / aij;
                Rp_cache[thread_id+0] = xij;
                Rp_cache[thread_id+16] = yij;
                Rp_cache[thread_id+32] = zij;
                Rp_cache[thread_id+48] = aij;
                Rp_cache[thread_id+64] = 1. / aij;
            } else {
                Rp_cache[thread_id+0] = 2e5;
                Rp_cache[thread_id+16] = 2e5;
                Rp_cache[thread_id+32] = 2e5;
                Rp_cache[thread_id+48] = 1.; // aij
                Rp_cache[thread_id+64] = 1.;
            }
        }
        int task_ij = task_ij0 + tx;
        if (task_ij >= npairs_ij) {
            task_ij = task_ij0;
        }
        int ij_loc0 = pair_ij_loc[task_ij];
        double *dm = jk.dm + ij_loc0;
        for (int n = ty; n < 56; n += 16) {
            dm_ij_cache[n*16] = dm[n];
        }
        double vj_ij[56];
#pragma unroll
        for (int ij = 0; ij < 56; ++ij) {
            vj_ij[ij] = 0;
        }
        for (int batch_kl = 0; batch_kl < 13; ++batch_kl) {
            int task_kl0 = blockIdx.y * 208 + batch_kl * 16;
            if (task_kl0 >= npairs_kl) {
                break;
            }
            if (qd_ij_max[batch_ij+blockIdx.x*tilex] + q_cond_kl[task_kl0] < bounds.cutoff &&
                qd_kl_max[batch_kl+blockIdx.y*13] + q_cond_ij[task_ij0] < bounds.cutoff) {
                continue;
            }

            int sq_kl = ty + batch_kl * 16;
            int task_ij = task_ij0 + tx;
            int task_kl = task_kl0 + ty;
            double fac = PI_FAC;
            if (task_ij >= npairs_ij || task_kl >= npairs_kl) {
                fac = 0.;
            }
            __syncthreads();
            double xij = Rp_cache[tx+0];
            double yij = Rp_cache[tx+16];
            double zij = Rp_cache[tx+32];
            double aij = Rp_cache[tx+48];
            double inv_aij = Rp_cache[tx+64];
            double xkl = Rq_cache[sq_kl+0];
            double ykl = Rq_cache[sq_kl+208];
            double zkl = Rq_cache[sq_kl+416];
            double akl = Rq_cache[sq_kl+624];
            double inv_akl = Rq_cache[sq_kl+832];
            double rs = rsqrt(aij+akl);
            fac = fac * (inv_aij * inv_akl * rs);
            double xpq = xij - xkl;
            double ypq = yij - ykl;
            double zpq = zij - zkl;
            double rr = xpq*xpq + ypq*ypq + zpq*zpq;
            double theta = aij * akl * (rs * rs);
            double omega = jk.omega;
            double gamma_inc[18];
            boys_fn(gamma_inc, theta, rr, omega, fac, 8, 0, 1);
            // the ket pair's Hermite density, with the phase (-1)^|k| of its components
            const double *dm_kl = jk.dm + pair_kl_loc[task_kl < npairs_kl ? task_kl : task_kl0];
            double dkl[20];
            dkl[0] = dm_kl[0];
            dkl[1] = -dm_kl[1];
            dkl[2] = dm_kl[2];
            dkl[3] = -dm_kl[3];
            dkl[4] = -dm_kl[4];
            dkl[5] = dm_kl[5];
            dkl[6] = -dm_kl[6];
            dkl[7] = dm_kl[7];
            dkl[8] = -dm_kl[8];
            dkl[9] = -dm_kl[9];
            dkl[10] = -dm_kl[10];
            dkl[11] = dm_kl[11];
            dkl[12] = -dm_kl[12];
            dkl[13] = dm_kl[13];
            dkl[14] = -dm_kl[14];
            dkl[15] = -dm_kl[15];
            dkl[16] = dm_kl[16];
            dkl[17] = -dm_kl[17];
            dkl[18] = -dm_kl[18];
            dkl[19] = -dm_kl[19];
            double vkl[20];
#pragma unroll
            for (int kl = 0; kl < 20; ++kl) {
                vkl[kl] = 0.;
            }
            vkl[0] += gamma_inc[0] * dm_ij_cache[0];
            vj_ij[0] += gamma_inc[0] * dkl[0];
            double r0_1_0_0 = xpq * gamma_inc[1];
            double r1_1_0_0 = xpq * gamma_inc[2];
            double r2_1_0_0 = xpq * gamma_inc[3];
            double r3_1_0_0 = xpq * gamma_inc[4];
            double r4_1_0_0 = xpq * gamma_inc[5];
            double r5_1_0_0 = xpq * gamma_inc[6];
            double r6_1_0_0 = xpq * gamma_inc[7];
            double r7_1_0_0 = xpq * gamma_inc[8];
            vkl[0] += r0_1_0_0 * dm_ij_cache[336];
            vj_ij[21] += r0_1_0_0 * dkl[0];
            vkl[10] += r0_1_0_0 * dm_ij_cache[0];
            vj_ij[0] += r0_1_0_0 * dkl[10];
            double r0_2_0_0 = xpq * r1_1_0_0 + gamma_inc[1];
            double r1_2_0_0 = xpq * r2_1_0_0 + gamma_inc[2];
            double r2_2_0_0 = xpq * r3_1_0_0 + gamma_inc[3];
            double r3_2_0_0 = xpq * r4_1_0_0 + gamma_inc[4];
            double r4_2_0_0 = xpq * r5_1_0_0 + gamma_inc[5];
            double r5_2_0_0 = xpq * r6_1_0_0 + gamma_inc[6];
            double r6_2_0_0 = xpq * r7_1_0_0 + gamma_inc[7];
            vkl[0] += r0_2_0_0 * dm_ij_cache[576];
            vj_ij[36] += r0_2_0_0 * dkl[0];
            vkl[10] += r0_2_0_0 * dm_ij_cache[336];
            vj_ij[21] += r0_2_0_0 * dkl[10];
            vkl[16] += r0_2_0_0 * dm_ij_cache[0];
            vj_ij[0] += r0_2_0_0 * dkl[16];
            double r0_3_0_0 = xpq * r1_2_0_0 + 2 * r1_1_0_0;
            double r1_3_0_0 = xpq * r2_2_0_0 + 2 * r2_1_0_0;
            double r2_3_0_0 = xpq * r3_2_0_0 + 2 * r3_1_0_0;
            double r3_3_0_0 = xpq * r4_2_0_0 + 2 * r4_1_0_0;
            double r4_3_0_0 = xpq * r5_2_0_0 + 2 * r5_1_0_0;
