            }
            if (tx == 0) { vj_kl_cache[sq_kl+3040] += vkl[38]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[39] += __shfl_down_sync(mask, vkl[39], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3120] -= vkl[39]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[40] += __shfl_down_sync(mask, vkl[40], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3200] -= vkl[40]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[41] += __shfl_down_sync(mask, vkl[41], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3280] += vkl[41]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[42] += __shfl_down_sync(mask, vkl[42], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3360] -= vkl[42]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[43] += __shfl_down_sync(mask, vkl[43], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3440] += vkl[43]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[44] += __shfl_down_sync(mask, vkl[44], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3520] -= vkl[44]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[45] += __shfl_down_sync(mask, vkl[45], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3600] -= vkl[45]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[46] += __shfl_down_sync(mask, vkl[46], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3680] -= vkl[46]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[47] += __shfl_down_sync(mask, vkl[47], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3760] += vkl[47]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[48] += __shfl_down_sync(mask, vkl[48], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3840] -= vkl[48]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[49] += __shfl_down_sync(mask, vkl[49], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+3920] += vkl[49]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[50] += __shfl_down_sync(mask, vkl[50], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+4000] -= vkl[50]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[51] += __shfl_down_sync(mask, vkl[51], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+4080] -= vkl[51]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[52] += __shfl_down_sync(mask, vkl[52], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+4160] += vkl[52]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[53] += __shfl_down_sync(mask, vkl[53], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+4240] -= vkl[53]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[54] += __shfl_down_sync(mask, vkl[54], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+4320] -= vkl[54]; }
            for (int offset = 8; offset > 0; offset /= 2) {
                vkl[55] += __shfl_down_sync(mask, vkl[55], offset);
            }
            if (tx == 0) { vj_kl_cache[sq_kl+4400] -= vkl[55]; }
        }
        {
        double *vj_cache = Rp_cache;
        int task_ij = task_ij0 + tx;
#pragma unroll
        for (int n = 0; n < 56; ++n) {
            __syncthreads();
            vj_cache[thread_id] = vj_ij[n];
            for (int stride = 8; stride > 0; stride /= 2) {
                __syncthreads();
                if (ty < stride) {
                    vj_cache[thread_id] += vj_cache[thread_id + stride*16];
                }
            }
            __syncthreads();
            if (ty == 0 && task_ij < npairs_ij) {
                atomicAdd(vj+ij_loc0+n, vj_cache[thread_id]);
            }
        }
        }
    }
    __syncthreads();
    for (int n = tx; n < 280; n += 16) {
        int kl = n / 5;
        int batch_kl = n - kl * 5;
        int sq_kl = ty + batch_kl * 16;
        int task_kl = blockIdx.y * 80 + sq_kl;
        if (task_kl < npairs_kl) {
            int kl_loc0 = pair_kl_loc[task_kl];
            atomicAdd(vj+kl_loc0+kl, vj_kl_cache[sq_kl+kl*80]);
        }
    }
}

// lij=6, lkl=4: TILEX=48 (largest; run-time tilex), TILEY=8
__global__ __launch_bounds__(256, 1) static
void md_j_gen_6_4(KERNEL_ARGS)
{
    KERNEL_SETUP();
    // the bra tile, from the grid that md_j_gen_grid_x chose
    int tilex = ((bounds.npairs_ij + 15) / 16 + gridDim.x - 1) / gridDim.x;
    int *pair_ij_mapping = bounds.pair_ij_mapping;
    int *pair_kl_mapping = bounds.pair_kl_mapping;
    int task_ij0 = block_x * (16*tilex);
    int task_kl0 = block_y * 128;
    if (q_cond_ij[task_ij0] + q_cond_kl[task_kl0] < bounds.cutoff) {
        return;
    }
    int sq_id = tx + 16 * ty;
    int thread_id = sq_id;
    int *bas = envs.bas;
    int *pair_ij_loc = bounds.pair_ij_loc;
    int *pair_kl_loc = bounds.pair_kl_loc;
    int nbas = envs.nbas;
    double *env = envs.env;
    double *vj = jk.vj;
    unsigned int lane_id = thread_id % 32;
    unsigned int group_id = lane_id / 16;
    unsigned int mask = 0xffff << (group_id * 16);

    int npairs_ij = bounds.npairs_ij;
    int npairs_kl = bounds.npairs_kl;
    double *Rq_cache = vj_kl_cache + 4480;
    double *Rp_cache = Rq_cache + 640;
    double *dm_ij_cache = Rp_cache + 80 + tx;
    float *qd_ij_max = bounds.qd_ij_max;
    float *qd_kl_max = bounds.qd_kl_max;
    for (int n = thread_id; n < 5200; n += 256) {
        vj_kl_cache[n] = 0.;
    }
    __syncthreads();

    for (int n = thread_id; n < 128; n += 256) {
        int task_kl = blockIdx.y * 128 + n;
        if (task_kl < npairs_kl) {
            int pair_kl = pair_kl_mapping[task_kl];
            int ksh = pair_kl / nbas;
            int lsh = pair_kl % nbas;
            double ak = env[bas[ksh*BAS_SLOTS+PTR_EXP]];
            double al = env[bas[lsh*BAS_SLOTS+PTR_EXP]];
            double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
            double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
            double akl = ak + al;
            double xkl = (ak * rk[0] + al * rl[0]) / akl;
            double ykl = (ak * rk[1] + al * rl[1]) / akl;
            double zkl = (ak * rk[2] + al * rl[2]) / akl;
            Rq_cache[n+0] = xkl;
            Rq_cache[n+128] = ykl;
            Rq_cache[n+256] = zkl;
            Rq_cache[n+384] = akl;
            Rq_cache[n+512] = 1. / akl;
        } else {
            Rq_cache[n+0] = 2e5;
            Rq_cache[n+128] = 2e5;
            Rq_cache[n+256] = 2e5;
            Rq_cache[n+384] = 1.;
            Rq_cache[n+512] = 1.;
        }
    }

    for (int batch_ij = 0; batch_ij < tilex; ++batch_ij) {
        int task_ij0 = blockIdx.x * (16*tilex) + batch_ij * 16;
        if (task_ij0 >= npairs_ij) {
            break;
        }
        __syncthreads();
        if (thread_id < 16) {
            int task_ij = task_ij0 + thread_id;
            if (task_ij < npairs_ij) {
                int pair_ij = pair_ij_mapping[task_ij];
                int ish = pair_ij / nbas;
                int jsh = pair_ij % nbas;
                double ai = env[bas[ish*BAS_SLOTS+PTR_EXP]];
                double aj = env[bas[jsh*BAS_SLOTS+PTR_EXP]];
                double *ri = env + bas[ish*BAS_SLOTS+PTR_BAS_COORD];
                double *rj = env + bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
                double aij = ai + aj;
                double xij = (ai * ri[0] + aj * rj[0]) / aij;
                double yij = (ai * ri[1] + aj * rj[1]) / aij;
                double zij = (ai * ri[2] + aj * rj[2]) / aij;
                Rp_cache[thread_id+0] = xij;
                Rp_cache[thread_id+16] = yij;
                Rp_cache[thread_id+32] = zij;
                Rp_cache[thread_id+48] = aij;
                Rp_cache[thread_id+64] = 1. / aij;
            } else {
                Rp_cache[thread_id+0] = 2e5;
                Rp_cache[thread_id+16] = 2e5;
                Rp_cache[thread_id+32] = 2e5;
                Rp_cache[thread_id+48] = 1.; // aij
                Rp_cache[thread_id+64] = 1.;
            }
        }
        int task_ij = task_ij0 + tx;
        if (task_ij >= npairs_ij) {
            task_ij = task_ij0;
        }
        int ij_loc0 = pair_ij_loc[task_ij];
        double *dm = jk.dm + ij_loc0;
        for (int n = ty; n < 84; n += 16) {
            dm_ij_cache[n*16] = dm[n];
        }
        double vj_ij[84];
#pragma unroll
        for (int ij = 0; ij < 84; ++ij) {
            vj_ij[ij] = 0;
        }
        for (int batch_kl = 0; batch_kl < 8; ++batch_kl) {
            int task_kl0 = blockIdx.y * 128 + batch_kl * 16;
            if (task_kl0 >= npairs_kl) {
                break;
            }
            if (qd_ij_max[batch_ij+blockIdx.x*tilex] + q_cond_kl[task_kl0] < bounds.cutoff &&
                qd_kl_max[batch_kl+blockIdx.y*8] + q_cond_ij[task_ij0] < bounds.cutoff) {
                continue;
            }

            int sq_kl = ty + batch_kl * 16;
            int task_ij = task_ij0 + tx;
            int task_kl = task_kl0 + ty;
            double fac = PI_FAC;
            if (task_ij >= npairs_ij || task_kl >= npairs_kl) {
                fac = 0.;
            }
            __syncthreads();
            double xij = Rp_cache[tx+0];
            double yij = Rp_cache[tx+16];
            double zij = Rp_cache[tx+32];
            double aij = Rp_cache[tx+48];
            double inv_aij = Rp_cache[tx+64];
            double xkl = Rq_cache[sq_kl+0];
            double ykl = Rq_cache[sq_kl+128];
            double zkl = Rq_cache[sq_kl+256];
            double akl = Rq_cache[sq_kl+384];
            double inv_akl = Rq_cache[sq_kl+512];
            double rs = rsqrt(aij+akl);
            fac = fac * (inv_aij * inv_akl * rs);
            double xpq = xij - xkl;
            double ypq = yij - ykl;
            double zpq = zij - zkl;
            double rr = xpq*xpq + ypq*ypq + zpq*zpq;
            double theta = aij * akl * (rs * rs);
            double omega = jk.omega;
            double gamma_inc[22];
            boys_fn(gamma_inc, theta, rr, omega, fac, 10, 0, 1);
            // the ket pair's Hermite density, with the phase (-1)^|k| of its components
            const double *dm_kl = jk.dm + pair_kl_loc[task_kl < npairs_kl ? task_kl : task_kl0];
            double dkl[35];
            dkl[0] = dm_kl[0];
            dkl[1] = -dm_kl[1];
            dkl[2] = dm_kl[2];
            dkl[3] = -dm_kl[3];
            dkl[4] = dm_kl[4];
            dkl[5] = -dm_kl[5];
            dkl[6] = dm_kl[6];
            dkl[7] = -dm_kl[7];
            dkl[8] = dm_kl[8];
            dkl[9] = dm_kl[9];
            dkl[10] = -dm_kl[10];
            dkl[11] = dm_kl[11];
            dkl[12] = -dm_kl[12];
            dkl[13] = dm_kl[13];
            dkl[14] = dm_kl[14];
            dkl[15] = -dm_kl[15];
            dkl[16] = dm_kl[16];
            dkl[17] = -dm_kl[17];
            dkl[18] = dm_kl[18];
            dkl[19] = dm_kl[19];
            dkl[20] = -dm_kl[20];
            dkl[21] = dm_kl[21];
            dkl[22] = -dm_kl[22];
            dkl[23] = dm_kl[23];
            dkl[24] = dm_kl[24];
            dkl[25] = dm_kl[25];
            dkl[26] = -dm_kl[26];
            dkl[27] = dm_kl[27];
            dkl[28] = -dm_kl[28];
            dkl[29] = dm_kl[29];
            dkl[30] = dm_kl[30];
            dkl[31] = -dm_kl[31];
            dkl[32] = dm_kl[32];
            dkl[33] = dm_kl[33];
            dkl[34] = dm_kl[34];
            double vkl[35];
#pragma unroll
            for (int kl = 0; kl < 35; ++kl) {
                vkl[kl] = 0.;
            }
            vkl[0] += gamma_inc[0] * dm_ij_cache[0];
            vj_ij[0] += gamma_inc[0] * dkl[0];
            double r0_1_0_0 = xpq * gamma_inc[1];
            double r1_1_0_0 = xpq * gamma_inc[2];
            double r2_1_0_0 = xpq * gamma_inc[3];
            double r3_1_0_0 = xpq * gamma_inc[4];
            double r4_1_0_0 = xpq * gamma_inc[5];
            double r5_1_0_0 = xpq * gamma_inc[6];
            double r6_1_0_0 = xpq * gamma_inc[7];
            double r7_1_0_0 = xpq * gamma_inc[8];
            double r8_1_0_0 = xpq * gamma_inc[9];
            double r9_1_0_0 = xpq * gamma_inc[10];
            vkl[0] += r0_1_0_0 * dm_ij_cache[448];
            vj_ij[28] += r0_1_0_0 * dkl[0];
            vkl[15] += r0_1_0_0 * dm_ij_cache[0];
            vj_ij[0] += r0_1_0_0 * dkl[15];
            double r0_2_0_0 = xpq * r1_1_0_0 + gamma_inc[1];
            double r1_2_0_0 = xpq * r2_1_0_0 + gamma_inc[2];
            double r2_2_0_0 = xpq * r3_1_0_0 + gamma_inc[3];
            double r3_2_0_0 = xpq * r4_1_0_0 + gamma_inc[4];
            double r4_2_0_0 = xpq * r5_1_0_0 + gamma_inc[5];
            double r5_2_0_0 = xpq * r6_1_0_0 + gamma_inc[6];
            double r6_2_0_0 = xpq * r7_1_0_0 + gamma_inc[7];
            double r7_2_0_0 = xpq * r8_1_0_0 + gamma_inc[8];
            double r8_2_0_0 = xpq * r9_1_0_0 + gamma_inc[9];
            vkl[0] += r0_2_0_0 * dm_ij_cache[784];
            vj_ij[49] += r0_2_0_0 * dkl[0];
            vkl[15] += r0_2_0_0 * dm_ij_cache[448];
            vj_ij[28] += r0_2_0_0 * dkl[15];
            vkl[25] += r0_2_0_0 * dm_ij_cache[0];
            vj_ij[0] += r0_2_0_0 * dkl[25];
            double r0_3_0_0 = xpq * r1_2_0_0 + 2 * r1_1_0_0;
            double r1_3_0_0 = xpq * r2_2_0_0 + 2 * r2_1_0_0;
            double r2_3_0_0 = xpq * r3_2_0_0 + 2 * r3_1_0_0;
            double r3_3_0_0 = xpq * r4_2_0_0 + 2 * r4_1_0_0;
            double r4_3_0_0 = xpq * r5_2_0_0 + 2 * r5_1_0_0;
            double r5_3_0_0 = xpq * r6_2_0_0 + 2 * r6_1_0_0;
            double r6_3_0_0 = xpq * r7_2_0_0 + 2 * r7_1_0_0;
            double r7_3_0_0 = xpq * r8_2_0_0 + 2 * r8_1_0_0;
            vkl[0] += r0_3_0_0 * dm_ij_cache[1024];
            vj_ij[64] += r0_3_0_0 * dkl[0];
            vkl[15] += r0_3_0_0 * dm_ij_cache[784];
            vj_ij[49] += r0_3_0_0 * dkl[15];
            vkl[25] += r0_3_0_0 * dm_ij_cache[448];
            vj_ij[28] += r0_3_0_0 * dkl[25];
            vkl[31] += r0_3_0_0 * dm_ij_cache[0];
            vj_ij[0] += r0_3_0_0 * dkl[31];
            double r0_4_0_0 = xpq * r1_3_0_0 + 3 * r1_2_0_0;
            double r1_4_0_0 = xpq * r2_3_0_0 + 3 * r2_2_0_0;
            double r2_4_0_0 = xpq * r3_3_0_0 + 3 * r3_2_0_0;
            double r3_4_0_0 = xpq * r4_3_0_0 + 3 * r4_2_0_0;
            double r4_4_0_0 = xpq * r5_3_0_0 + 3 * r5_2_0_0;
            double r5_4_0_0 = xpq * r6_3_0_0 + 3 * r6_2_0_0;
            double r6_4_0_0 = xpq * r7_3_0_0 + 3 * r7_2_0_0;
            vkl[0] += r0_4_0_0 * dm_ij_cache[1184];
            vj_ij[74] += r0_4_0_0 * dkl[0];
            vkl[15] += r0_4_0_0 * dm_ij_cache[1024];
            vj_ij[64] += r0_4_0_0 * dkl[15];
            vkl[25] += r0_4_0_0 * dm_ij_cache[784];
            vj_ij[49] += r0_4_0_0 * dkl[25];
            vkl[31] += r0_4_0_0 * dm_ij_cache[448];
            vj_ij[28] += r0_4_0_0 * dkl[31];
            vkl[34] += r0_4_0_0 * dm_ij_cache[0];
            vj_ij[0] += r0_4_0_0 * dkl[34];
            double r0_5_0_0 = xpq * r1_4_0_0 + 4 * r1_3_0_0;
            double r1_5_0_0 = xpq * r2_4_0_0 + 4 * r2_3_0_0;
            double r2_5_0_0 = xpq * r3_4_0_0 + 4 * r3_3_0_0;
            double r3_5_0_0 = xpq * r4_4_0_0 + 4 * r4_3_0_0;
            double r4_5_0_0 = xpq * r5_4_0_0 + 4 * r5_3_0_0;
            double r5_5_0_0 = xpq * r6_4_0_0 + 4 * r6_3_0_0;
            vkl[0] += r0_5_0_0 * dm_ij_cache[1280];
            vj_ij[80] += r0_5_0_0 * dkl[0];
            vkl[15] += r0_5_0_0 * dm_ij_cache[1184];
            vj_ij[74] += r0_5_0_0 * dkl[15];
            vkl[25] += r0_5_0_0 * dm_ij_cache[1024];
            vj_ij[64] += r0_5_0_0 * dkl[25];
            vkl[31] += r0_5_0_0 * dm_ij_cache[784];
            vj_ij[49] += r0_5_0_0 * dkl[31];
            vkl[34] += r0_5_0_0 * dm_ij_cache[448];
            vj_ij[28] += r0_5_0_0 * dkl[34];
            double r0_6_0_0 = xpq * r1_5_0_0 + 5 * r1_4_0_0;
            double r1_6_0_0 = xpq * r2_5_0_0 + 5 * r2_4_0_0;
            double r2_6_0_0 = xpq * r3_5_0_0 + 5 * r3_4_0_0;
            double r3_6_0_0 = xpq * r4_5_0_0 + 5 * r4_4_0_0;
            double r4_6_0_0 = xpq * r5_5_0_0 + 5 * r5_4_0_0;
            vkl[0] += r0_6_0_0 * dm_ij_cache[1328];
            vj_ij[83] += r0_6_0_0 * dkl[0];
            vkl[15] += r0_6_0_0 * dm_ij_cache[1280];
            vj_ij[80] += r0_6_0_0 * dkl[15];
            vkl[25] += r0_6_0_0 * dm_ij_cache[1184];
            vj_ij[74] += r0_6_0_0 * dkl[25];
            vkl[31] += r0_6_0_0 * dm_ij_cache[1024];
            vj_ij[64] += r0_6_0_0 * dkl[31];
            vkl[34] += r0_6_0_0 * dm_ij_cache[784];
            vj_ij[49] += r0_6_0_0 * dkl[34];
            double r0_7_0_0 = xpq * r1_6_0_0 + 6 * r1_5_0_0;
            double r1_7_0_0 = xpq * r2_6_0_0 + 6 * r2_5_0_0;
            double r2_7_0_0 = xpq * r3_6_0_0 + 6 * r3_5_0_0;
            double r3_7_0_0 = xpq * r4_6_0_0 + 6 * r4_5_0_0;
            vkl[15] += r0_7_0_0 * dm_ij_cache[1328];
            vj_ij[83] += r0_7_0_0 * dkl[15];
            vkl[25] += r0_7_0_0 * dm_ij_cache[1280];
            vj_ij[80] += r0_7_0_0 * dkl[25];
            vkl[31] += r0_7_0_0 * dm_ij_cache[1184];
            vj_ij[74] += r0_7_0_0 * dkl[31];
            vkl[34] += r0_7_0_0 * dm_ij_cache[1024];
            vj_ij[64] += r0_7_0_0 * dkl[34];
            double r0_8_0_0 = xpq * r1_7_0_0 + 7 * r1_6_0_0;
            double r1_8_0_0 = xpq * r2_7_0_0 + 7 * r2_6_0_0;
            double r2_8_0_0 = xpq * r3_7_0_0 + 7 * r3_6_0_0;
            vkl[25] += r0_8_0_0 * dm_ij_cache[1328];
