// gridDim.x of a generated J launch: bra tiles of at most tilex_max batches of 16 pairs, enough of them that the
// grid has at least MD_J_GEN_BLOCKS_PER_SM blocks per SM (twice that if bra and ket share their pairs), and only as
// many as the tiles of ceil(nbatch / gridDim.x) batches fill (as md_j_grid_x in unrolled_md_j.cu)
#define MD_J_GEN_BLOCKS_PER_SM 64
static int md_j_gen_grid_x(int npairs_ij, int tilex_max, int grid_y, int diagonal)
{
    int dev, n_sm;
    cudaGetDevice(&dev);
    cudaDeviceGetAttribute(&n_sm, cudaDevAttrMultiProcessorCount, dev);
    int nbatch = (npairs_ij + 15) / 16;
    int gx = (nbatch + tilex_max - 1) / tilex_max;
    int want = MD_J_GEN_BLOCKS_PER_SM * n_sm * (diagonal ? 2 : 1);
    if (gx * grid_y < want && nbatch > 0) {
        gx = std::min(nbatch, (want + grid_y - 1) / grid_y);
        int tilex = (nbatch + gx - 1) / gx;
        gx = (nbatch + tilex - 1) / tilex;
    }
    return std::max(gx, 1);
}

int md_j_generated(RysIntEnvVars *envs, JKMatrix *jk, MDBoundsInfo *bounds,
                   float *q_cond_ij, float *q_cond_kl, double omega)
{
    int npairs_ij = bounds->npairs_ij;
    int npairs_kl = bounds->npairs_kl;
    int diagonal = bounds->pair_ij_mapping == bounds->pair_kl_mapping;
    dim3 threads(16, 16);
    switch (bounds->lij*11 + bounds->lkl) {
    case 36: { // TILEY=13, 44800 bytes of shared memory
        dim3 blocks(md_j_gen_grid_x(npairs_ij, 48, (npairs_kl + 207) / 208, diagonal),
                    (npairs_kl + 207) / 208, 1);
        cudaFuncSetAttribute(md_j_gen_3_3, cudaFuncAttributeMaxDynamicSharedMemorySize, 44800);
        md_j_gen_3_3<<<blocks, threads, 44800>>>(*envs, *jk, *bounds, q_cond_ij, q_cond_kl);
    } break;
    case 46: { // TILEY=22, 47360 bytes of shared memory
        dim3 blocks(md_j_gen_grid_x(npairs_ij, 48, (npairs_kl + 351) / 352, diagonal),
                    (npairs_kl + 351) / 352, 1);
        cudaFuncSetAttribute(md_j_gen_4_2, cudaFuncAttributeMaxDynamicSharedMemorySize, 47360);
